class StockPortfolioTracker:
    def __init__(self, cash_balance):
        self.portfolio = []
        self.cash_balance = cash_balance

    def add_stock(self, stock):
        for pf in self.portfolio:
            if self._is_same_stock(pf, stock):
                pf['quantity'] += stock['quantity']
                return
        self.portfolio.append(stock)

    def remove_stock(self, stock):
        for pf in self.portfolio:
            if self._is_same_stock(pf, stock) and pf['quantity'] >= stock['quantity']:
                pf['quantity'] -= stock['quantity']
                if pf['quantity'] == 0:
                    self.portfolio.remove(pf)
                return True
        return False

    def buy_stock(self, stock):
        if self._is_insufficient_funds(stock):
            return False
        self.add_stock(stock)
        self.cash_balance -= self._get_stock_value(stock)
        return True

    def sell_stock(self, stock):
        if not self.remove_stock(stock):
            return False
        self.cash_balance += self._get_stock_value(stock)
        return True

    def calculate_portfolio_value(self):
        total_value = self.cash_balance
        for stock in self.portfolio:
            total_value += self._get_stock_value(stock)
        return total_value

    def get_portfolio_summary(self):
        summary = [
            {"name": stock["name"], "value": self._get_stock_value(stock)}
            for stock in self.portfolio
        ]
        portfolio_value = self.calculate_portfolio_value()
        return portfolio_value, summary

    def _get_stock_value(self, stock):
        return stock['price'] * stock['quantity']

    def _is_same_stock(self, pf, stock):
        return pf['name'] == stock['name']

    def _is_insufficient_funds(self, stock):
        return self._get_stock_value(stock) > self.cash_balance
